set -eu; sudo install -d -o syslog -g adm -m 0750 /var/log/inventory; sudo tee /etc/rsyslog.d/30-inventory-collector.conf >/dev/null <<'ANTRIEB_EOF'
module(load="imtcp")
template(name="InventoryLine" type="string" string="%timereported:::date-rfc3339% %hostname% %syslogtag%%msg%\n")
ruleset(name="inventory_remote") {
  if ($fromhost-ip == "10.100.137.11" and $programname == "inventory") then {
    action(type="omfile" file="/var/log/inventory/node2.log" template="InventoryLine" fileOwner="syslog" fileGroup="adm" fileCreateMode="0640" dirCreateMode="0750")
  }
  stop
}
input(type="imtcp" port="514" ruleset="inventory_remote")
ANTRIEB_EOF
sudo rsyslogd -N1; sudo systemctl restart rsyslog; systemctl is-active rsyslog; ss -lntp | grep ':514 '; sudo sed -n '1,120p' /etc/rsyslog.d/30-inventory-collector.conf

